import json
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
g=[[0]*30 for _ in range(30)]
starts=[1,8,15,22]
# tile cells including border
for i,r in enumerate(starts):
 for j,c in enumerate(starts):
  for y in range(r,r+5):
   for x in range(c,c+5):
    g[y][x]=4
  for y in range(r+1,r+4):
   for x in range(c+1,c+4): g[y][x]=colors[i][j]
# connect minority tile colors across row/column separators; common tile color 2 is ignored
for i,row in enumerate(colors):
 for col in (3,8):
  poss=[j for j,v in enumerate(row) if v==col]
  if len(poss)>1:
   for j in range(min(poss),max(poss)):
    # gap between tile j and j+1: c starts +5,+6; maintain same interior row span
    for y in range(starts[i]+1, starts[i]+4):
     for x in (starts[j]+5, starts[j]+6): g[y][x]=col
for j in range(4):
 vals=[colors[i][j] for i in range(4)]
 for col in (3,8):
  poss=[i for i,v in enumerate(vals) if v==col]
  if len(poss)>1:
   for i in range(min(poss),max(poss)):
    for y in (starts[i]+5,starts[i]+6):
     for x in range(starts[j]+1,starts[j]+4): g[y][x]=col
print(json.dumps(g))
